def money(value: float, symbol: str) -> str:
    return f"{symbol}{value:,.2f}"


def percent(value: float) -> str:
    return f"{value:.2%}"


def float_input(
    label: str,
    value: float,
    min_value: float = 0.0,
    max_value: float | None = None,
    step: float = 1.0,
    help_text: str | None = None,
    number_format: str = "%.2f",
) -> float:
    return float(
        st.number_input(
            label,
            min_value=None if min_value is None else float(min_value),
            max_value=None if max_value is None else float(max_value),
            value=float(value),
            step=None if step is None else float(step),
            format=number_format,
            help=help_text,
        )
    )


def int_input(
    label: str,
    value: int,
    min_value: int = 0,
    max_value: int | None = None,
    step: int = 1,
    help_text: str | None = None,
    number_format: str = "%d",
) -> int:
    return int(
        st.number_input(
            label,
            min_value=None if min_value is None else int(min_value),
            max_value=None if max_value is None else int(max_value),
            value=int(value),
            step=None if step is None else int(step),
            format=number_format,
            help=help_text,
        )
    )


